/// A lightweight random state holding an 8-bit seed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RandomState {
    pub seed: u8,
}

/// Produces a deterministic pseudo-random `f32` in [0, 1)
/// by mapping the seed modulo 8 onto one of eight equally spaced values:
/// 0.0, 0.125, 0.25, 0.375, 0.5, 0.625, 0.75, 0.875.
///
/// Identical seeds always yield identical outputs.
pub fn random(state: RandomState) -> f32 {
    // Map `seed % 8` to {0,1,2,3,4,5,6,7}, then multiply by 1/8 = 0.125
    (state.seed % 8) as f32 * 0.125_f32
}

